const body = $input.first().json.body || $input.first().json;
const email = String(body.email || '').trim().toLowerCase();
const coupon = String(body.coupon_code || 'WELCOME20').trim();
const percent = Number(body.discount_percent || 20);
const optin = Boolean(body.optin);
const site = String(body.site || 'https://palmbeach-vitality.store/');
const source = String(body.source || 'homepage_lead_popup');

if (!email || !email.includes('@')) {
  throw new Error('Missing or invalid email');
}

const shopUrl = site.replace(/\/?$/, '/') + 'shop/';
const subject = `Your ${percent}% welcome code — Palm Beach Vitality`;
const text = [
  'Welcome to Palm Beach Vitality.',
  '',
  `Your new-client discount code is: ${coupon}`,
  `That's ${percent}% off your first order.`,
  '',
  `Apply it at checkout: ${shopUrl}`,
  '',
  'Questions? Reply to this email or write sales@palmbeach-vitality.com.',
].join('\n');

const html = `
  <p>Welcome to <strong>Palm Beach Vitality</strong>.</p>
  <p>Your new-client discount code is:</p>
  <p style="font-size:22px;font-weight:700;letter-spacing:0.04em;">${coupon}</p>
  <p>That's <strong>${percent}% off</strong> your first order.</p>
  <p><a href="${shopUrl}">Shop now</a> and enter the code at checkout.</p>
  <p style="color:#666;font-size:13px;">Questions? Reply to this email or write sales@palmbeach-vitality.com.</p>
`;

return [{
  json: {
    email,
    coupon_code: coupon,
    discount_percent: percent,
    optin,
    site,
    source,
    subject,
    text,
    html,
  }
}];
